// CLX Lead Scoring v2 — Parse Scoring Response
//
// Apollo bonus layering (Part B.5):
//   +10 if apollo_enriched_at is set (any verified Apollo data at all)
//   +15 if job_title_verified matches the insurance_broker decision-maker
//        keywords (mirror of niche_overlays.apollo_title_keywords)
// Bonus is clamped so the total lead_score never exceeds 100.

const response = $input.item.json;
const lead = $('Split In Batches').first().json;

const rawText = (response && response.content && response.content[0] && response.content[0].text) || '';

// Fail-closed guard. Scoring a lead with no research is what produced the
// 1,373 zeros: the model had nothing to reason about, returned something
// unparseable, and the catch block wrote a score anyway. If the context is
// missing we do not score, do not write a reason, and do not write
// components -- the lead stays unscored, which is the truth.
const hasResearch = Boolean(lead && String(lead.research_summary || '').trim());
if (!hasResearch) {
  console.log('SCORING SKIPPED:', JSON.stringify({ lead_id: lead && lead.id, reason: 'research_required' }));
  return {
    json: {
      id: lead && lead.id,
      lead_score: null,
      priority_level: null,
      decision_maker_probability: null,
      company_size_estimate: null,
      scoring_reason: null,
      score_components: null,
      lead_status: 'Research Failed',
      _scoring_error: 'research_required',
      updated_at: new Date().toISOString()
    }
  };
}

let scoring;
try {
  const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
  scoring = JSON.parse(cleaned);
} catch (e) {
  // A parse failure is not a score of zero. Persisting 0 / 'Low' / the error
  // text made 1,373 leads look deliberately judged worthless when the model
  // response simply never arrived intact -- and put parser output in the
  // customer-facing scoring_reason. Unscored and badly scored are different
  // states and must not look alike.
  scoring = {
    lead_score: null,
    priority_level: null,
    decision_maker_probability: null,
    company_size_estimate: null,
    scoring_reason: null,
    _scoring_error: 'parse_error: ' + String(e && e.message).slice(0, 200)
  };
}

// ── Apollo enrichment bonus (layered on top of Claude's base score) ──
const APOLLO_KEYWORDS = [
  'broker of record', 'principal', 'owner',
  'managing partner', 'president', 'founder'
];
const verifiedTitle = String(lead.job_title_verified || '').toLowerCase();
let apolloBonus = 0;
if (lead.apollo_enriched_at) apolloBonus += 10;
if (verifiedTitle && APOLLO_KEYWORDS.some(k => verifiedTitle.includes(k))) {
  apolloBonus += 15;
}

const scoredOk = typeof scoring.lead_score === 'number';
const baseScore = scoredOk ? scoring.lead_score : null;
// No base score means no final score. Adding the Apollo bonus to a failed
// parse would manufacture a 25 out of nothing.
const finalScore = scoredOk ? Math.min(100, baseScore + apolloBonus) : null;

// Structured explanation. The Apollo layer is deterministic and genuinely
// decomposable; Claude's base score is a judgement and is NOT broken into
// invented point values. The two are reported separately so the breakdown
// can never contradict the number.
const scoreComponents = scoredOk ? {
  final_score: finalScore,
  ai_base_score: baseScore,
  ai_assessment: {
    priority_level: scoring.priority_level || null,
    decision_maker_probability: scoring.decision_maker_probability || null,
    company_size_estimate: scoring.company_size_estimate || null,
    basis: 'model judgement, not arithmetic'
  },
  deterministic_bonus: {
    total: apolloBonus,
    apollo_enriched: lead.apollo_enriched_at ? 10 : 0,
    verified_decision_maker_title: (verifiedTitle && APOLLO_KEYWORDS.some(function(k){return verifiedTitle.indexOf(k)!==-1;})) ? 15 : 0,
    evidence: { apollo_enriched_at: lead.apollo_enriched_at || null, job_title_verified: lead.job_title_verified || null }
  },
  clamped_at_100: (baseScore + apolloBonus) > 100,
  scored_at: new Date().toISOString()
} : {
  final_score: null,
  status: 'not_scored',
  reason: scoring._scoring_error || 'model response unavailable'
};

const reasonSuffix = apolloBonus > 0
  ? ' [Apollo bonus +' + apolloBonus + ']'
  : '';

const now = new Date().toISOString();

// Defaults are only applied when scoring actually succeeded. Falling back to
// 'Low' / 'SMB' / 'Scored' on a failed parse is what dressed 1,373 unscored
// leads up as deliberate low-quality judgements.
return {
  json: {
    id: lead.id,
    lead_score: finalScore,
    priority_level: scoredOk ? (scoring.priority_level || 'Low') : null,
    decision_maker_probability: scoredOk ? (scoring.decision_maker_probability || 'Low') : null,
    company_size_estimate: scoredOk ? (scoring.company_size_estimate || 'SMB') : null,
    scoring_reason: scoredOk ? ((scoring.scoring_reason || '') + reasonSuffix) : null,
    score_components: scoreComponents,
    lead_status: scoredOk ? 'Scored' : 'Scoring Failed',
    _scoring_error: scoring._scoring_error || null,
    updated_at: now
  }
};

// CLX Lead Scoring v2 — Prep Update Score

const item = $input.item.json;

const body = {
  p_lead_id: item.id,
  p_fields: {
    lead_score: item.lead_score,
    priority_level: item.priority_level,
    decision_maker_probability: item.decision_maker_probability,
    company_size_estimate: item.company_size_estimate,
    scoring_reason: item.scoring_reason,
    score_components: item.score_components,
    // Only claim 'Scored' when a score exists. The hardcoded 'Scored' here is
    // what let 1,373 failed parses enter the funnel as scored leads.
    lead_status: item.lead_score === null ? 'Scoring Failed' : 'Scored'
  }
};

if (item._scoring_error) {
  // leads has no scoring_error column and update_lead uses an explicit
  // allowlist, so the execution log is where this is visible.
  console.log('SCORING PARSE FAILURE:', JSON.stringify({ lead_id: item.id, error: item._scoring_error }));
}

console.log('PREP UPDATE:', JSON.stringify({ lead_id: item.id, status: body.p_fields.lead_status, score: item.lead_score }));

return { json: { ...item, rpc_body: JSON.stringify(body) } };
